mapper.select:
select r.id,r.reserve_user_id,m.reserve_quantity,m.no as materialNo,b.material_batch_no,m.material_id, b.expired_date,b.material_id,m.material_position_id,p.position as materialPositionName, p.code as materialPositionCode, m.id as storageMaterialId,b.hydration,b.no_hydration_content,m.unit_id,b.supplier,b.producer, m.available_quantity,m.sign_status from bm_storage_material_reserve r left join bm_storage_material m on r.storage_material_id = m.id left join bm_storage_material_batch b on m.storage_material_batch_id = b.id left join bm_cargo_position p on m.material_position_id = p.id left join bm_ingredient_weigh_record wr on wr.storage_material_id = m.id where r.is_deleted = 0
and r.batch_id = #{productPlanId}
and m.material_id = #{materialId}
order by b.material_batch_no ASC, CAST(m.no AS UNSIGNED) ASC

select r.*
from bm_storage_material_reserve r
left join bm_storage_material m on r.storage_material_id = m.id
where r.is_deleted = 0

    and r.batch_id = #{planId}


    and m.material_id  = #{materialId}

select r.id,r.reserve_user_id,m.reserve_quantity,m.no as materialNo,b.material_batch_no,m.material_id, b.expired_date,b.material_id,m.material_position_id,p.position as materialPositionName, p.code as materialPositionCode, m.id as storageMaterialId,b.hydration,b.no_hydration_content,m.unit_id,b.supplier,b.producer, m.available_quantity,m.sign_status from bm_storage_material_reserve r left join bm_storage_material m on r.storage_material_id = m.id left join bm_storage_material_batch b on m.storage_material_batch_id = b.id left join bm_cargo_position p on m.material_position_id = p.id left join bm_ingredient_weigh_record wr on wr.storage_material_id = m.id where r.is_deleted = 0
and r.batch_id = #{productPlanId}
and m.material_id in
#{materialId}
order by b.material_batch_no ASC,m.no ASC
